const input = $input.first().json.body;

const workflowPayload = {
  name: `[Marketplace] ${input.agentName || 'Code Review Agent'}`,
  nodes: [
    {
      parameters: {
        httpMethod: 'POST',
        path: `marketplace/agent/${input.agentName || 'code-review'}/trigger`,
        responseMode: 'lastNode',
        options: {}
      },
      name: 'Webhook Trigger',
      type: 'n8n-nodes-base.webhook',
      typeVersion: 2,
      position: [250, 300]
    },
    {
      parameters: {
        model: input.model || 'qwen2.5:7b-instruct-q4_K_M',
        prompt: `You are a code review assistant. Review the following code changes and provide constructive feedback.\n\nRepository: ${input.repoUrl}\n\nChanges:\n{{ $json.body.changes }}`,
        options: {
          baseUrl: 'http://ollama:11434'
        }
      },
      name: 'Ollama Code Review',
      type: '@n8n/n8n-nodes-langchain.lmChatOllama',
      typeVersion: 1,
      position: [470, 300]
    }
  ],
  connections: {
    'Webhook Trigger': {
      main: [[
        { node: 'Ollama Code Review', type: 'main', index: 0 }
      ]]
    }
  },
  settings: {
    executionOrder: 'v1'
  },
  active: true
};

return [{ json: { workflowPayload, agentConfig: input } }];

